mapper.select:
select l.log_id, l.member_id, l.action, l.dept_id, d.dept_name, l.before_json, l.after_json, l.operator_id, l.operator_name, l.ip, l.create_time, m.name as member_name, m.student_no from oa_member_log l left join oa_member m on m.member_id = l.member_id left join sys_dept d on d.dept_id = l.dept_id
and l.member_id = #{memberId}
and l.action = #{action}
and l.operator_name like concat('%', #{operatorName}, '%')
and l.dept_id = #{deptId}
and (m.name like concat('%', #{keyword}, '%') or m.student_no like concat(#{keyword}, '%'))
and l.create_time >= concat(#{params.beginTime}, ' 00:00:00')
and l.create_time <= concat(#{params.endTime}, ' 23:59:59')
${params.dataScope}
order by l.log_id desc
